<?php
$is_form=!$unavailable && $action!=='details';
$is_edit=$action==='edit'; $is_schedule=$action==='schedule'; $is_confirm=$action==='confirm';
$values=['expense_category_id'=>'','payment_method_id'=>'','description'=>'','amount'=>'','expense_date'=>date('Y-m-d'),'expense_treatment'=>'operating','notes'=>'','frequency'=>'monthly','repeat_every'=>'1','start_date'=>date('Y-m-d'),'end_date'=>''];
if ($row) { $values=array_replace($values,$row); }
if ($schedule) { foreach (['expense_category_id','payment_method_id','description','amount','expense_treatment'] as $field) { $values[$field]=$schedule[$field]; } }
if ($_SERVER['REQUEST_METHOD']==='POST') { foreach ($values as $field=>$value) { if (isset($_POST[$field]) && is_string($_POST[$field])) { $values[$field]=$_POST[$field]; } } }
$url=app_url('user/expense_action.php').'?action='.$action.($modal?'&modal=1':'');
?>
<?php if ($is_form): ?><form method="post" enctype="multipart/form-data" action="<?= e($url) ?>" class="expense-form" <?= $modal?'data-expense-async novalidate':'' ?>><?php endif; ?>
<div class="<?= $modal?'modal-header':'expense-form-heading' ?>"><div><h2 class="modal-title" id="expense-modal-title"><?= e($page_title) ?></h2><?php if ($row): ?><p class="modal-subtitle">EXP-<?= e($row['expense_id']) ?></p><?php endif; ?></div><?php if ($modal): ?><button class="btn-close" type="button" data-bs-dismiss="modal" aria-label="Close"></button><?php endif; ?></div>
<div class="<?= $modal?'modal-body':'expense-form-body' ?>">
    <div class="alert alert-danger expense-submit-error <?= !$error?'d-none':'' ?>" role="alert" tabindex="-1"><?= e($error??'') ?></div>
    <?php if ($unavailable): ?>
    <?php elseif ($action==='details'): ?>
        <div class="expense-detail-amount"><span class="payment-badge status-<?= $row['expense_status']==='void'?'refunded':'paid' ?>"><?= $row['expense_status']==='void'?'Voided':'Recorded' ?></span><h3><?= e(sale_money($row['amount'])) ?></h3><p><?= e($row['description']) ?></p></div>
        <dl class="expense-details"><div><dt>Category</dt><dd><?= e($row['category_name']) ?></dd></div><div><dt>Date</dt><dd><?= e((new DateTimeImmutable($row['expense_date']))->format('j M Y')) ?></dd></div><div><dt>Payment method</dt><dd><?= e($row['method_name']) ?></dd></div><div><dt>Type</dt><dd><?= e(['operating'=>'Operating expense','inventory_purchase'=>'Stock / inventory purchase','other_cash_outflow'=>'Other cash payment'][$row['expense_treatment']]) ?></dd></div><?php if ($row['recurrence_due_on']): ?><div><dt>Scheduled for</dt><dd><?= e($row['recurrence_due_on']) ?></dd></div><?php endif; ?></dl>
        <?php if ($row['notes']): ?><h3 class="expense-section-title">Notes</h3><p class="sale-notes"><?= nl2br(e($row['notes'])) ?></p><?php endif; ?>
        <?php if ($row['expense_status']==='void'): ?><div class="alert alert-light"><strong>Void reason:</strong> <?= e($row['void_reason']) ?></div><?php endif; ?>
        <h3 class="expense-section-title">Receipt</h3>
        <?php if ($row['receipts']): $latest=$row['receipts'][0]; ?><a href="<?= e(app_url('user/expense_receipt.php?id='.$latest['receipt_id'])) ?>" target="_blank" rel="noopener"><img class="expense-receipt-preview" src="<?= e(app_url('user/expense_receipt.php?id='.$latest['receipt_id'])) ?>" alt="Receipt for <?= e($row['description']) ?>"></a><a class="sales-text-link" href="<?= e(app_url('user/expense_receipt.php?id='.$latest['receipt_id'].'&download=1')) ?>">Download receipt</a><?php if (count($row['receipts'])>1): ?><details class="expense-old-receipts"><summary>Previous receipts</summary><?php foreach (array_slice($row['receipts'],1) as $receipt): ?><p><a href="<?= e(app_url('user/expense_receipt.php?id='.$receipt['receipt_id'])) ?>" target="_blank" rel="noopener"><?= e($receipt['original_filename']) ?></a> · <?= e($receipt['uploaded_at']) ?></p><?php endforeach; ?></details><?php endif; ?>
        <?php else: ?><p class="sale-modal-note">No receipt attached.</p><?php endif; ?>
    <?php else: ?>
        <input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="expense_id" value="<?= e($row['expense_id']??'') ?>"><input type="hidden" name="schedule_id" value="<?= e($schedule['recurring_expense_id']??'') ?>">
        <?php foreach ($token as $key=>$value): ?><input type="hidden" name="<?= e($key) ?>" value="<?= e($value) ?>"><?php endforeach; ?>
        <?php if ($row): ?><input type="hidden" name="revision" value="<?= e(expense_revision($row)) ?>"><?php endif; ?>
        <?php if ($action==='void'): ?>
            <p class="expense-void-description"><?= e($row['description']) ?></p><strong class="expense-void-amount"><?= e(sale_money($row['amount'])) ?></strong><p class="sale-modal-note mt-3">This removes the expense from active totals and applicable profit calculations. Its history and receipts are kept. This does not return money from your supplier.</p>
            <label class="form-label" for="void_reason">Reason for voiding</label><textarea class="form-control" id="void_reason" name="void_reason" rows="3" maxlength="255" required><?= e(post_text('void_reason')) ?></textarea>
        <?php elseif ($action==='toggle'): ?>
            <input type="hidden" name="revision" value="<?= e(hash('sha256',json_encode($schedule,JSON_THROW_ON_ERROR))) ?>"><p><?= e($schedule['description']) ?></p><p class="sale-modal-note"><?= $schedule['is_active']?'Pause this schedule? Existing paid expenses stay in history.':'Resume this schedule? No expense is created until you confirm a payment.' ?></p>
        <?php elseif ($action==='category'): ?>
            <label class="form-label" for="category_name">Category name</label><input class="form-control" id="category_name" name="category_name" maxlength="100" placeholder="For example, Transportation" value="<?= e(post_text('category_name')) ?>" required><p class="form-text">Existing category names are reused. An inactive matching category is enabled again.</p>
        <?php else: ?>
            <?php if ($is_edit): ?><div class="alert alert-light expense-edit-note">You can update the description, notes, and receipt. To change the amount, category, date, or payment method, void this expense and record a corrected one.</div><dl class="expense-details"><div><dt>Category</dt><dd><?= e($row['category_name']) ?></dd></div><div><dt>Amount</dt><dd><?= e(sale_money($row['amount'])) ?></dd></div><div><dt>Date</dt><dd><?= e($row['expense_date']) ?></dd></div><div><dt>Payment method</dt><dd><?= e($row['method_name']) ?></dd></div></dl><?php endif; ?>
            <?php if ($is_confirm): ?><div class="alert alert-light">Confirm an actual paid expense for the occurrence due <?= e($schedule['next_due_date']) ?>. Recording it advances this schedule once.</div><input type="hidden" name="recurring_expense_id" value="<?= e($id) ?>"><input type="hidden" name="recurrence_due_on" value="<?= e($schedule['next_due_date']) ?>"><?php endif; ?>
            <?php if ($is_confirm): ?><?php foreach (['expense_category_id','payment_method_id','expense_treatment'] as $field): ?><input type="hidden" name="<?= e($field) ?>" value="<?= e($values[$field]) ?>"><?php endforeach; ?><?php endif; ?>
            <?php if (!$is_edit && !$is_confirm && !array_filter($catalog['categories'],fn($category)=>$category['is_active'])): ?><p class="alert alert-light">Add your first expense category before recording an expense.</p><?php endif; ?>
            <div class="row g-3">
            <?php if (!$is_edit): ?>
                <div class="col-sm-6"><label class="form-label" for="expense_category_id">Expense category</label><select class="form-select" id="expense_category_id" name="expense_category_id" required <?= $is_confirm?'disabled':'' ?>><option value="">Choose a category</option><?php foreach ($catalog['categories'] as $category): ?><?php if ($category['is_active'] || ($is_confirm && (string)$category['expense_category_id']===(string)$values['expense_category_id'])): ?><option value="<?= e($category['expense_category_id']) ?>" <?= (string)$category['expense_category_id']===(string)$values['expense_category_id']?'selected':'' ?>><?= e($category['category_name']) ?></option><?php endif; ?><?php endforeach; ?></select><?php if (!$is_confirm): ?><a class="expense-category-link" data-expense-modal="category" href="<?= e(app_url('user/expense_action.php?action=category')) ?>">Add category</a><?php endif; ?></div>
                <div class="col-sm-6"><label class="form-label" for="amount">Amount (PHP)</label><input class="form-control" type="number" id="amount" name="amount" min="0.01" max="99999999999.99" step="0.01" value="<?= e($values['amount']) ?>" <?= $is_confirm?'readonly':'' ?> required></div>
            <?php endif; ?>
                <div class="col-12"><label class="form-label" for="description">Expense description</label><input class="form-control" id="description" name="description" maxlength="255" placeholder="For example, packaging materials for orders" value="<?= e($values['description']) ?>" required></div>
            <?php if (!$is_edit): ?>
                <?php if (!$is_schedule): ?><div class="col-sm-6"><label class="form-label" for="expense_date">Expense date</label><input class="form-control" type="date" id="expense_date" name="expense_date" max="<?= e(date('Y-m-d')) ?>" value="<?= e($values['expense_date']) ?>" required></div><?php endif; ?>
                <div class="col-sm-6"><label class="form-label" for="payment_method_id">Payment method</label><select class="form-select" id="payment_method_id" name="payment_method_id" required <?= $is_confirm?'disabled':'' ?>><option value="">Choose a method</option><?php foreach ($catalog['methods'] as $method): ?><option value="<?= e($method['payment_method_id']) ?>" <?= (string)$method['payment_method_id']===(string)$values['payment_method_id']?'selected':'' ?>><?= e($method['method_name']) ?></option><?php endforeach; ?></select></div>
                <div class="col-sm-6"><label class="form-label" for="expense_treatment">Expense type</label><select class="form-select" id="expense_treatment" name="expense_treatment" required <?= $is_confirm?'disabled':'' ?>><?php foreach (['operating'=>'Operating expense','inventory_purchase'=>'Stock / inventory purchase','other_cash_outflow'=>'Other cash payment'] as $key=>$label): ?><option value="<?= e($key) ?>" <?= $key===$values['expense_treatment']?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select><p class="form-text">Stock purchases and other cash payments are kept in history, but excluded from operating expenses and profit deductions.</p></div>
            <?php endif; ?>
            <?php if ($is_schedule): ?>
                <div class="col-sm-6"><label class="form-label" for="frequency">Repeat</label><select class="form-select" id="frequency" name="frequency"><?php foreach (['daily'=>'Daily','weekly'=>'Weekly','monthly'=>'Monthly','yearly'=>'Yearly'] as $key=>$label): ?><option value="<?= e($key) ?>" <?= $values['frequency']===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></div><div class="col-sm-6"><label class="form-label" for="repeat_every">Every how many periods?</label><input class="form-control" type="number" id="repeat_every" name="repeat_every" min="1" max="365" value="<?= e($values['repeat_every']) ?>" required></div><div class="col-sm-6"><label class="form-label" for="start_date">First due date</label><input class="form-control" type="date" id="start_date" name="start_date" value="<?= e($values['start_date']) ?>" required></div><div class="col-sm-6"><label class="form-label" for="end_date">End date <span class="field-optional">(optional)</span></label><input class="form-control" type="date" id="end_date" name="end_date" value="<?= e($values['end_date']) ?>"></div><div class="col-12"><p class="sale-modal-note">This schedule does not count as an expense. Record a payment only after the expense is actually paid.</p></div>
            <?php else: ?>
                <div class="col-12"><label class="form-label" for="receipt"><?= $is_edit?'New receipt':'Receipt attachment' ?> <span class="field-optional">(optional)</span></label><input class="form-control" type="file" id="receipt" name="receipt" accept="image/jpeg,image/png,image/webp"><p class="form-text">JPG, PNG or WebP, up to 2 MB. <?= $is_edit?'The newest upload becomes the current receipt; earlier attachments stay in history.':'Receipts are visible only to your business account.' ?></p></div><div class="col-12"><label class="form-label" for="notes">Notes <span class="field-optional">(optional)</span></label><textarea class="form-control" id="notes" name="notes" rows="2" maxlength="4000"><?= e($values['notes']) ?></textarea></div>
            <?php endif; ?>
            </div>
        <?php endif; ?>
    <?php endif; ?>
</div>
<div class="<?= $modal?'modal-footer':'expense-form-footer' ?>">
    <?php if ($modal): ?><button class="btn btn-outline-secondary" type="button" data-bs-dismiss="modal"><?= $is_form?'Cancel':'Close' ?></button><?php else: ?><a class="btn btn-outline-secondary" href="<?= e(app_url('user/expenses.php')) ?>">Cancel</a><?php endif; ?>
    <?php if ($is_form): $label=match($action) {'void'=>'Confirm Void','schedule'=>'Save Schedule','toggle'=>$schedule['is_active']?'Pause Schedule':'Resume Schedule','category'=>'Save Category',default=>'Save Expense'}; ?><button class="btn <?= $action==='void'?'btn-danger':'btn-primary' ?>" type="submit" data-submit-label="<?= e($label) ?>"><?= e($label) ?></button><?php endif; ?>
</div>
<?php if ($is_form): ?></form><?php endif; ?>
